${pagingTop} SELECT homepage_id, individual_idx, user_name, user_phone, user_email, user_affiliation, postcode, address_base, address_detailed, book_area, book_quantity, reader_contest, relay_plan, relay_personnel, approval_status, delete_yn, add_id, add_date FROM BOOK_RELAY_INDIVIDUAL WHERE homepage_id = #{homepage_id} AND delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY individual_idx DESC ${pagingBottom}

