UPDATE 
	BOOK_RELAY_INDIVIDUAL
SET
	delete_yn = 'Y',
	delete_id = #{delete_id}
WHERE
	homepage_id = #{homepage_id}
AND individual_idx = #{individual_idx}

UPDATE 
	BOOK_RELAY_INDIVIDUAL
SET
	approval_status = #{approval_status}
WHERE
	homepage_id = #{homepage_id}
AND individual_idx = #{individual_idx}
